llm.raw_content:
{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C18"],
      "claim": "Clopenthixol, a chloro-thioxanthene antipsychotic with the same tricyclic core as the query, has absolute oral bioavailability of 40–60% in humans, directly supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C45"],
      "claim": "Flupenthixol, another thioxanthene antipsychotic, has mean systemic availability of 55% (range 48–60%) after oral tablets versus IV, supporting high bioavailability for the thioxanthene class.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "Cyclobenzaprine, which shares the dimethylaminopropylidene side chain, has mean oral bioavailability 0.55 (90% CI 0.51–0.60) versus IV, supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C41"],
      "claim": "Amitriptyline, with the same dimethylaminopropylidene side chain, has absolute oral bioavailability 47.7 ± 11% in healthy volunteers, supporting high bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C12"],
      "claim": "Doxepin, with the same side chain and a tricyclic ether core, has absolute bioavailability 0.29, still above the 20% threshold, supporting high bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C32"],
      "claim": "Prochlorperazine, a phenothiazine with a piperazine side chain, has low absolute bioavailability (12.5 ± 4.3%), providing contradictory evidence but from a less transferable chemotype.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C43"],
      "claim": "Zotepine, a dibenzothiepine with a chloro substituent, has bioavailability 7–13%, contradictory but with lower structural transfer to the thioxanthene query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The closest and most transferable evidence—chloro-thioxanthene antipsychotics clopenthixol (F 40–60%) and flupenthixol (F ~55%)—directly supports F ≥ 20%. Additional analogues sharing the dimethylaminopropylidene side chain (cyclobenzaprine, amitriptyline, doxepin) also show F ≥ 20%. Contradictory low-F records come from less similar phenothiazine/dibenzothiepine chemotypes and are outweighed. Prediction: high.",
  "evidence_gaps": [
    "No direct absolute bioavailability measurement for chlorprothixene itself; closest evidence is from clopenthixol/flupenthixol with different side chains.",
    "Low-F analogues (zotepine, prochlorperazine) are from different chemotypes and may not capture query-specific first-pass metabolism."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

